//! ♻️ Original typed-source custody returns its exact unpublished reservation before its owned payload.
use super::*;
pub fn original_typed_source_close_demands<A:ArtifactApp>(source:&OriginalTypedCommandSource<A>,_body:usize)->Result<semio_framework_value::RetirementDemand,ValueError>{if source.operation.is_some()&&source.receipt.is_none(){return Ok(semio_framework_value::RetirementDemand{copy_bytes:(1+usize::from(source.host_event))*std::mem::size_of::<Option<u64>>()+std::mem::size_of::<Option<semio_framework_job::Operation>>(),depth:1,..Default::default()})}source.close_demands()}
pub fn close_original_typed_source<A:ArtifactApp>(source:&mut OriginalTypedCommandSource<A>,reservations:&mut [Option<u64>;semio_plugin_ownership::bounded_ownership::ARTIFACT_LIVE_OUTPUT_SLOTS],markers:&mut semio_plugin_instance_history::history_components::HostEventOperations,cx:&mut semio_framework_job::StepContext<'_>)->Result<semio_framework_value::RetainedCloneStep,semio_framework_job::OriginalTurnFailure>{source.validate(cx)?;let before=cx.retained_progress();if let Some(operation)=source.operation.filter(|_|source.receipt.is_none()){let id=operation.operation.0;let index=id as usize%reservations.len();if reservations[index]!=Some(id)||source.command.is_none()||source.metadata.is_none()||source.caller.is_none(){return Err(ValueError::invariant("host event source lost its exact unpublished reservation").into())}let d=original_typed_source_close_demands(source,cx.retained_grant().maximum_copy_bytes)?;cx.with_original_retirement(|cx|{semio_framework_job::close_original_retained_step(cx,d,|_|{source.operation=None;reservations[index]=None;markers.remove(&id);semio_framework_value::RetainedWorkOutcome::<_,semio_framework_value::ValueError>{result:Ok(semio_framework_value::RetainedCloneStep::Progress(semio_framework_value::RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})),work:1}})?;Ok(())})?;}else{cx.with_original_retirement(|cx|source.close_step(cx))?;}Ok(semio_framework_value::RetainedCloneStep::Progress(semio_plugin_ownership::bounded_ownership::original_lifecycle_delta(before,cx.retained_progress())?))}
